function legalOrder(order: Detail['orders'][number]): string {
  const l = order.legal;
  if (l?.status === 'accepted' && l.url && /^\/(?:de\/|en\/)?legal\/versions\/\d{4}-\d{2}-\d{2}\/cgv$/.test(l.url)) {
    return `<br/><small>CGV acceptées · <a href="${e(l.url)}" target="_blank" rel="noopener">${e(l.terms_version)} · ${e(l.locale?.toUpperCase())}</a> · ${date(l.event_created_at,true)}</small>`;
  }
  return `<br/><small>${l?.status === 'unverified' ? 'CGV : preuve à contrôler' : 'CGV : acceptation versionnée non collectée'}</small>`;
}
const $ = <T extends HTMLElement=HTMLElement>(id:string) => document.getElementById(id) as T;
const e = (v:unknown) => String(v ?? '').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]!));
const nf = new Intl.NumberFormat('fr-CH');
const num = (n:number|null|undefined) => n == null ? '—' : nf.format(n);
const money = (c:number) => new Intl.NumberFormat('fr-CH',{minimumFractionDigits:c%100?2:0,maximumFractionDigits:2}).format(c/100);
const date = (v:string|number|null|undefined, time=false) => {
 if(!v)return 'Non enregistré';
 const parsed=new Date(v);
 if(!Number.isFinite(parsed.getTime())||(typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isCalendarDate(v)))return 'Date à vérifier';
 return new Intl.DateTimeFormat('fr-CH',{timeZone:'Europe/Zurich',day:'2-digit',month:'short',year:time?undefined:'numeric',...(time?{hour:'2-digit',minute:'2-digit'}:{})}).format(parsed);
};
const initials = (s:string) => e(s.replace(/@.*/,'').split(/[ ._-]/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase());
