const states:Record<string,string>={delivered:'Livré',sent:'Envoyé',opened:'Ouverture signalée',clicked:'Clic signalé',bounced:'Rejeté',delivery_delayed:'Livraison retardée',complained:'Plainte',failed:'Échec',unread:'Non lu',seen:'Lu dans la boîte',queued:'En attente',scheduled:'Programmé'};
const sectionInfo:Record<string,[string,string,string]>={overview:['Vue d’ensemble','VOTRE ACTIVITÉ, EN CLAIR','Les chiffres utiles. Les prochaines actions. Le reste à portée de main.'],clients:['Clients','UNE RELATION, UNE VUE COMPLÈTE','Achats, accès, échanges et prochaines actions au même endroit.'],mail:['Messagerie','GARDER LE FIL','Les messages du projet et leur livraison, reliés à vos clients.'],audience:['Audience','COMPRENDRE LES VISITES','Séparer les visites estimées, les robots et l’usage des services.'],visibility:['Visibilité','ÊTRE TROUVÉ','Ce que Google montre et ce qui amène des visiteurs sur le site.'],data:['Données & qualité','LA CONFIANCE COMMENCE ICI','Les versions réellement disponibles et la fraîcheur des sources.'],operations:['Automatisations','SAVOIR CE QUI TOURNE','Derniers passages, réussites vérifiées et points à reprendre.']};
let active = Object.hasOwn(sectionInfo,location.hash.slice(1)) ? location.hash.slice(1) : 'overview';
